import os
import glob
import numpy as np
import pandas as pd
import tensorflow as tf

from scipy import interpolate
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import (
    accuracy_score,
    balanced_accuracy_score,
    f1_score
)

# ============================================================
# 0. Basic configuration
# ============================================================

# Real-world data with fixed split labels (generated by fixed_split.py)
REAL_DATA_PATH = "./LPD_with_split.csv"

# Output directory for validation results
OUTPUT_DIR = "./deeplearning_results"

os.makedirs(OUTPUT_DIR, exist_ok=True)

# Model directories corresponding to each random seed
SEED_MODEL_DIRS = {
    0: "../models/seed_0/length_50_100/deeplearning",
    1: "../models/seed_1/length_50_100/deeplearning",
    2: "../models/seed_2/length_50_100/deeplearning",
    3: "../models/seed_3/length_50_100/deeplearning",
    42: "../models/seed_42/length_50_100/deeplearning"
}

# Five random seeds
SEEDS = [0, 1, 2, 3, 42]

# Target length for interpolation
TARGET_LENGTH = 100

# Number of classes
NUM_CLASSES = 5

# Nine synthetic pre-training configurations
CONFIGURATIONS = [
    "multiplicative_low",
    "multiplicative_medium",
    "multiplicative_high",

    "multiplicative_outlier_low",
    "multiplicative_outlier_medium",
    "multiplicative_outlier_high",

    "additive_multiplicative_low",
    "additive_multiplicative_medium",
    "additive_multiplicative_high"
]

# Two deep learning model types
MODEL_TYPES = [
    "cnn",
    "inceptiontime"
]


# ============================================================
# 1. Load the fixed validation set
# ============================================================

def load_validation_data(file_path):
    """
    Load the fixed validation split from the per-timestep dataset,
    interpolate each series to TARGET_LENGTH, and standardize each
    series independently.
    """

    print("=" * 80)
    print("Step 1: Loading fixed validation set")
    print("=" * 80)

    df = pd.read_csv(file_path)

    print(f"Number of rows in the full per-timestep dataset: {len(df)}")
    print(f"Columns: {df.columns.tolist()}")

    # --------------------------------------------------------
    # Check required columns
    # --------------------------------------------------------

    required_columns = [
        "class_label",
        "sample_id",
        "time_step_id",
        "value",
        "split"
    ]

    for col in required_columns:
        if col not in df.columns:
            raise ValueError(
                f"Missing required column in data: {col}"
            )

    # --------------------------------------------------------
    # Keep only the validation split
    # --------------------------------------------------------

    df = df[
        df["split"].astype(str).str.lower()
        == "validation"
    ].copy()

    if len(df) == 0:
        raise ValueError(
            "No samples with split == validation were found."
        )

    # --------------------------------------------------------
    # Construct unique_id if absent
    # --------------------------------------------------------

    if "unique_id" not in df.columns:

        df["unique_id"] = (
            df["class_label"].astype(str)
            + "_"
            + df["sample_id"].astype(str)
        )

    # --------------------------------------------------------
    # Sample-level processing
    # --------------------------------------------------------

    samples = []
    labels = []
    sample_ids = []

    for unique_id, group in df.groupby(
        "unique_id",
        sort=False
    ):

        group = group.sort_values(
            "time_step_id"
        )

        values = (
            group["value"]
            .astype(float)
            .values
        )

        label = int(
            group["class_label"].iloc[0]
        )

        seq_len = len(values)

        # ====================================================
        # Interpolate to TARGET_LENGTH points
        # ====================================================

        if seq_len == TARGET_LENGTH:

            resampled = values.copy()

        else:

            orig_time = np.arange(
                seq_len
            )

            target_time = np.linspace(
                0,
                seq_len - 1,
                TARGET_LENGTH
            )

            f = interpolate.interp1d(
                orig_time,
                values,
                kind="linear",
                fill_value="extrapolate"
            )

            resampled = f(
                target_time
            )

        # ====================================================
        # Standardize each time series independently
        # ====================================================

        scaler = StandardScaler()

        resampled_scaled = scaler.fit_transform(
            resampled.reshape(-1, 1)
        ).flatten()

        samples.append(
            resampled_scaled
        )

        labels.append(
            label
        )

        sample_ids.append(
            unique_id
        )

    # Input format for CNN / InceptionTime
    X = np.array(
        samples,
        dtype=np.float32
    )[:, :, np.newaxis]

    y = np.array(
        labels,
        dtype=int
    )

    print(
        f"\nNumber of validation samples: {len(y)}"
    )

    print(
        f"X shape: {X.shape}"
    )

    print(
        "\nValidation class distribution:"
    )

    print(
        pd.Series(y)
        .value_counts()
        .sort_index()
    )

    if len(y) != 224:

        print(
            "\nWARNING:"
        )

        print(
            f"Current validation sample count is {len(y)}, "
            f"expected 224."
        )

    return X, y, sample_ids


# ============================================================
# 2. Locate model files
# ============================================================

def find_model_file(
        seed,
        model_type,
        configuration
):
    """
    Find the model file for a given seed in the corresponding folder.

    Example:
        seed 0  -> final0
        seed 1  -> final1
        seed 2  -> final2
        seed 3  -> final3
        seed 42 -> final42
    """

    if seed not in SEED_MODEL_DIRS:

        return None

    model_dir = SEED_MODEL_DIRS[seed]

    # --------------------------------------------------------
    # Prefer the standard filenames
    # --------------------------------------------------------

    possible_files = [

        os.path.join(
            model_dir,
            f"{model_type}_{configuration}.h5"
        ),

        os.path.join(
            model_dir,
            f"{model_type}_{configuration}.keras"
        )
    ]

    for path in possible_files:

        if os.path.isfile(path):

            return path

    # --------------------------------------------------------
    # Fall back to fuzzy matching if the standard name is missing
    # --------------------------------------------------------

    search_patterns = [

        os.path.join(
            model_dir,
            f"*{model_type}*{configuration}*.h5"
        ),

        os.path.join(
            model_dir,
            f"*{model_type}*{configuration}*.keras"
        )
    ]

    candidates = []

    for pattern in search_patterns:

        candidates.extend(
            glob.glob(pattern)
        )

    # Remove duplicates
    candidates = list(
        dict.fromkeys(
            candidates
        )
    )

    if len(candidates) == 1:

        return candidates[0]

    elif len(candidates) > 1:

        print(
            f"\nWARNING: Seed {seed} matched multiple candidate models:"
        )

        for p in candidates:

            print(
                "  ",
                p
            )

        print(
            "Using the first match by default:"
        )

        print(
            candidates[0]
        )

        return candidates[0]

    return None


# ============================================================
# 3. Evaluate a single model
# ============================================================

def evaluate_model(
        model,
        X,
        y_true
):
    """
    Evaluate a single model on the validation set and return
    accuracy, balanced accuracy, macro-F1, probabilities, and predictions.
    """

    # --------------------------------------------------------
    # Softmax probabilities
    # --------------------------------------------------------

    y_pred_proba = model.predict(
        X,
        verbose=0
    )

    y_pred = np.argmax(
        y_pred_proba,
        axis=1
    )

    # --------------------------------------------------------
    # Accuracy
    # --------------------------------------------------------

    accuracy = accuracy_score(
        y_true,
        y_pred
    )

    # --------------------------------------------------------
    # Balanced accuracy
    # --------------------------------------------------------

    balanced_accuracy = balanced_accuracy_score(
        y_true,
        y_pred
    )

    # --------------------------------------------------------
    # Macro-F1
    # --------------------------------------------------------

    macro_f1 = f1_score(
        y_true,
        y_pred,
        average="macro",
        zero_division=0
    )

    return {
        "accuracy":
            accuracy,

        "balanced_accuracy":
            balanced_accuracy,

        "macro_f1":
            macro_f1,

        "probabilities":
            y_pred_proba,

        "predictions":
            y_pred
    }


# ============================================================
# 4. Main
# ============================================================

def main():

    # ========================================================
    # Step 1
    # Load the validation set
    # ========================================================

    X_val, y_val, sample_ids = load_validation_data(
        REAL_DATA_PATH
    )

    print(
        "\n"
        + "=" * 80
    )

    print(
        "Step 2: Evaluating 9 synthetic pre-training configurations"
    )

    print(
        "=" * 80
    )

    seed_level_results = []

    # ========================================================
    # Iterate over the 9 configurations
    # ========================================================

    for configuration in CONFIGURATIONS:

        print(
            "\n"
            + "#" * 80
        )

        print(
            f"Configuration: {configuration}"
        )

        print(
            "#" * 80
        )

        # ====================================================
        # CNN / InceptionTime
        # ====================================================

        for model_type in MODEL_TYPES:

            print(
                f"\n[{model_type.upper()}]"
            )

            # =================================================
            # Five seeds
            # =================================================

            for seed in SEEDS:

                print(
                    f"\nSeed = {seed}"
                )

                # ---------------------------------------------
                # Locate the model file
                # ---------------------------------------------

                model_path = find_model_file(
                    seed,
                    model_type,
                    configuration
                )

                if model_path is None:

                    print(
                        "Model file not found."
                    )

                    print(
                        f"Seed: {seed}"
                    )

                    print(
                        f"Model type: {model_type}"
                    )

                    print(
                        f"Configuration: {configuration}"
                    )

                    print(
                        f"Directory: {SEED_MODEL_DIRS[seed]}"
                    )

                    continue

                print(
                    f"Model path:"
                )

                print(
                    model_path
                )

                # ---------------------------------------------
                # Load the model
                # ---------------------------------------------

                try:

                    model = tf.keras.models.load_model(
                        model_path
                    )

                except Exception as e:

                    print(
                        "Failed to load model:"
                    )

                    print(e)

                    continue

                # ---------------------------------------------
                # Validation evaluation
                # ---------------------------------------------

                metrics = evaluate_model(
                    model,
                    X_val,
                    y_val
                )

                print(
                    f"Accuracy = "
                    f"{metrics['accuracy']:.4f}"
                )

                print(
                    f"Balanced Accuracy = "
                    f"{metrics['balanced_accuracy']:.4f}"
                )

                print(
                    f"Macro F1 = "
                    f"{metrics['macro_f1']:.4f}"
                )

                # ---------------------------------------------
                # Save seed-level results
                # ---------------------------------------------

                seed_level_results.append(
                    {
                        "configuration":
                            configuration,

                        "model_type":
                            model_type,

                        "seed":
                            seed,

                        "accuracy":
                            metrics[
                                "accuracy"
                            ],

                        "balanced_accuracy":
                            metrics[
                                "balanced_accuracy"
                            ],

                        "macro_f1":
                            metrics[
                                "macro_f1"
                            ],

                        "model_path":
                            model_path
                    }
                )

                # ---------------------------------------------
                # Clean up the TensorFlow session
                # ---------------------------------------------

                del model

                tf.keras.backend.clear_session()


    # ========================================================
    # Step 3
    # Check whether any model was successfully evaluated
    # ========================================================

    if len(seed_level_results) == 0:

        raise RuntimeError(
            "\nNo model was successfully evaluated.\n"
            "Please check:\n"
            "1. Model file paths\n"
            "2. Model file names\n"
            "3. Whether the H5 / Keras files can be loaded normally"
        )

    seed_df = pd.DataFrame(
        seed_level_results
    )


    # ========================================================
    # Step 4
    # Save the per-seed raw results
    # ========================================================

    seed_output = os.path.join(
        OUTPUT_DIR,
        "Table10_seed_level_validation_results.csv"
    )

    seed_df.to_csv(
        seed_output,
        index=False,
        encoding="utf-8-sig"
    )

    print(
        "\n"
        + "=" * 80
    )

    print(
        "Step 3: Seed-level results saved"
    )

    print(
        "=" * 80
    )

    print(
        seed_output
    )


    # ========================================================
    # Step 5
    # Check whether each model + configuration has all 5 seeds
    # ========================================================

    print(
        "\n"
        + "=" * 80
    )

    print(
        "Step 4: Checking seed completeness"
    )

    print(
        "=" * 80
    )

    seed_counts = (
        seed_df
        .groupby(
            [
                "configuration",
                "model_type"
            ]
        )
        ["seed"]
        .nunique()
    )

    print(
        seed_counts
    )

    incomplete = seed_counts[
        seed_counts != 5
    ]

    if len(incomplete) > 0:

        print(
            "\nWARNING:"
        )

        print(
            "The following combinations do not have all 5 seeds:"
        )

        print(
            incomplete
        )

        print(
            "\nPlease check the corresponding model files in the final* folders."
        )

    else:

        print(
            "\nAll configuration + model_type combinations "
            "contain all 5 seeds."
        )


    # ========================================================
    # Step 6
    # Summarize mean +- SD
    # ========================================================

    summary_df = (
        seed_df
        .groupby(
            [
                "configuration",
                "model_type"
            ]
        )
        .agg(
            N_seeds=(
                "seed",
                "nunique"
            ),

            accuracy_mean=(
                "accuracy",
                "mean"
            ),

            accuracy_sd=(
                "accuracy",
                "std"
            ),

            balanced_accuracy_mean=(
                "balanced_accuracy",
                "mean"
            ),

            balanced_accuracy_sd=(
                "balanced_accuracy",
                "std"
            ),

            macro_f1_mean=(
                "macro_f1",
                "mean"
            ),

            macro_f1_sd=(
                "macro_f1",
                "std"
            )
        )
        .reset_index()
    )


    # ========================================================
    # Convert to percentage
    # ========================================================

    summary_df[
        "accuracy_mean_pct"
    ] = (
        summary_df[
            "accuracy_mean"
        ]
        * 100
    )

    summary_df[
        "accuracy_sd_pct"
    ] = (
        summary_df[
            "accuracy_sd"
        ]
        * 100
    )


    # ========================================================
    # Format as required by the manuscript:
    # 94.8% +- 0.8%
    # ========================================================

    summary_df[
        "accuracy_mean_sd"
    ] = summary_df.apply(

        lambda row:

        (
            f"{row['accuracy_mean_pct']:.1f}% "
            f"+- "
            f"{row['accuracy_sd_pct']:.1f}%"
        ),

        axis=1
    )


    # ========================================================
    # Save the full summary
    # ========================================================

    summary_output = os.path.join(
        OUTPUT_DIR,
        "Table10_validation_summary.csv"
    )

    summary_df.to_csv(
        summary_output,
        index=False,
        encoding="utf-8-sig"
    )


    # ========================================================
    # Step 7
    # Build the manuscript version of Table 10
    # ========================================================

    cnn_df = (
        summary_df[
            summary_df[
                "model_type"
            ]
            == "cnn"
        ][
            [
                "configuration",
                "accuracy_mean_sd"
            ]
        ]
        .rename(
            columns={
                "accuracy_mean_sd":
                    "CNN"
            }
        )
    )

    inception_df = (
        summary_df[
            summary_df[
                "model_type"
            ]
            == "inceptiontime"
        ][
            [
                "configuration",
                "accuracy_mean_sd"
            ]
        ]
        .rename(
            columns={
                "accuracy_mean_sd":
                    "InceptionTime"
            }
        )
    )


    table10 = pd.merge(
        cnn_df,
        inception_df,
        on="configuration",
        how="outer"
    )


    # ========================================================
    # Fix the order of the nine configurations
    # ========================================================

    table10[
        "configuration"
    ] = pd.Categorical(
        table10[
            "configuration"
        ],
        categories=CONFIGURATIONS,
        ordered=True
    )

    table10 = (
        table10
        .sort_values(
            "configuration"
        )
        .reset_index(
            drop=True
        )
    )


    table10 = table10.rename(
        columns={
            "configuration":
                "Pre-training configuration"
        }
    )


    # ========================================================
    # Save the manuscript version of Table 10
    # ========================================================

    table10_csv = os.path.join(
        OUTPUT_DIR,
        "Table10_FINAL_validation.csv"
    )

    table10_excel = os.path.join(
        OUTPUT_DIR,
        "Table10_FINAL_validation.xlsx"
    )

    table10.to_csv(
        table10_csv,
        index=False,
        encoding="utf-8-sig"
    )

    table10.to_excel(
        table10_excel,
        index=False
    )


    # ========================================================
    # Step 8
    # Print the final Table 10
    # ========================================================

    print(
        "\n"
        + "=" * 80
    )

    print(
        "FINAL TABLE 10"
    )

    print(
        "Validation set only"
    )

    print(
        "=" * 80
    )

    print(
        table10.to_string(
            index=False
        )
    )


    # ========================================================
    # Step 9
    # Select the best configuration by validation accuracy
    # ========================================================

    cnn_summary = (
        summary_df[
            summary_df[
                "model_type"
            ]
            == "cnn"
        ]
        .sort_values(
            "accuracy_mean",
            ascending=False
        )
    )

    inception_summary = (
        summary_df[
            summary_df[
                "model_type"
            ]
            == "inceptiontime"
        ]
        .sort_values(
            "accuracy_mean",
            ascending=False
        )
    )


    print(
        "\n"
        + "=" * 80
    )

    print(
        "BEST CONFIGURATION"
    )

    print(
        "Selected using VALIDATION set only"
    )

    print(
        "=" * 80
    )


    if len(cnn_summary) > 0:

        best_cnn = cnn_summary.iloc[0]

        print(
            "\nBest CNN configuration:"
        )

        print(
            best_cnn[
                "configuration"
            ]
        )

        print(
            "Validation Accuracy: "
            f"{best_cnn['accuracy_mean'] * 100:.2f}% "
            f"+- "
            f"{best_cnn['accuracy_sd'] * 100:.2f}%"
        )


    if len(inception_summary) > 0:

        best_inc = inception_summary.iloc[0]

        print(
            "\nBest InceptionTime configuration:"
        )

        print(
            best_inc[
                "configuration"
            ]
        )

        print(
            "Validation Accuracy: "
            f"{best_inc['accuracy_mean'] * 100:.2f}% "
            f"+- "
            f"{best_inc['accuracy_sd'] * 100:.2f}%"
        )


    # ========================================================
    # Step 10
    # Final notes
    # ========================================================

    print(
        "\n"
        + "=" * 80
    )

    print(
        "Table 10 evaluation completed."
    )

    print(
        "Only the 224 validation samples were used."
    )

    print(
        "The 225 held-out test samples were never accessed."
    )

    print(
        "The best pre-training configuration can now be fixed."
    )

    print(
        "=" * 80
    )

    print(
        "\nOutput files:"
    )

    print(
        table10_csv
    )

    print(
        table10_excel
    )

    print(
        summary_output
    )

    print(
        seed_output
    )


# ============================================================
# Program entry point
# ============================================================

if __name__ == "__main__":

    main()